 } = require("./gameEngine");

 const MIN_PLAYERS = 4;
 const MAX_PLAYERS = 8;
 const CONDITIONS = ["cadeirante", "cego", "surdo", "neuroatipico"];
 const SCHOOL_STAGES = ["Fundamental", "Médio", "Superior"];

 const shuffleArray = (array) => {
